package com.phoenix.business.config;
import com.phoenix.business.security.JwtFilter; import lombok.RequiredArgsConstructor; import org.springframework.beans.factory.annotation.Value; import org.springframework.context.annotation.*; import org.springframework.http.HttpMethod; import org.springframework.security.config.annotation.method.configuration.EnableMethodSecurity; import org.springframework.security.config.annotation.web.builders.HttpSecurity; import org.springframework.security.config.http.SessionCreationPolicy; import org.springframework.security.crypto.bcrypt.BCryptPasswordEncoder; import org.springframework.security.crypto.password.PasswordEncoder; import org.springframework.security.web.SecurityFilterChain; import org.springframework.security.web.authentication.UsernamePasswordAuthenticationFilter; import org.springframework.web.cors.*; import java.util.*;
@Configuration @EnableMethodSecurity @RequiredArgsConstructor public class SecurityConfig { private final JwtFilter jwt; @Bean PasswordEncoder passwordEncoder(){return new BCryptPasswordEncoder(12);} @Bean SecurityFilterChain filter(HttpSecurity h)throws Exception{return h.csrf(c->c.disable()).cors(c->{}).sessionManagement(s->s.sessionCreationPolicy(SessionCreationPolicy.STATELESS)).headers(x->x.contentSecurityPolicy(c->c.policyDirectives("default-src 'none'; frame-ancestors 'none'"))).authorizeHttpRequests(a->a.requestMatchers("/api/auth/login","/actuator/health","/api/public/branding","/api/public/branding-assets/*").permitAll().requestMatchers(HttpMethod.OPTIONS,"/**").permitAll().requestMatchers("/api/users/**").hasRole("OWNER").requestMatchers("/api/reports/**","/api/audit-logs/**").hasAnyRole("OWNER","ADMIN").requestMatchers(HttpMethod.PUT,"/api/settings").hasAnyRole("OWNER","ADMIN").requestMatchers(HttpMethod.POST,"/api/plans").hasAnyRole("OWNER","ADMIN").requestMatchers(HttpMethod.PUT,"/api/plans/**").hasAnyRole("OWNER","ADMIN").requestMatchers(HttpMethod.DELETE,"/api/members/**").hasAnyRole("OWNER","ADMIN").anyRequest().authenticated()).exceptionHandling(e->e.authenticationEntryPoint((q,r,x)->r.setStatus(401)).accessDeniedHandler((q,r,x)->r.setStatus(403))).addFilterBefore(jwt,UsernamePasswordAuthenticationFilter.class).build();} @Bean(name = "corsConfigurationSource") CorsConfigurationSource cors(@Value("${app.cors-origins}") String raw){CorsConfiguration c=new CorsConfiguration();c.setAllowedOrigins(Arrays.stream(raw.split(",")).map(String::trim).toList());c.setAllowedMethods(List.of("GET","POST","PUT","PATCH","DELETE","OPTIONS"));c.setAllowedHeaders(List.of("Authorization","Content-Type"));c.setExposedHeaders(List.of("Content-Disposition"));c.setAllowCredentials(true);c.setMaxAge(3600L);UrlBasedCorsConfigurationSource s=new UrlBasedCorsConfigurationSource();s.registerCorsConfiguration("/**",c);return s;} }
